create table if not exists clients(id bigint generated always as identity primary key,name text unique not null);
create table if not exists machines(id bigint generated always as identity primary key,code text unique not null,machine_group text not null);
create table if not exists employees(id bigint generated always as identity primary key,name text not null,shift text not null check(shift in ('Manhã','Tarde','Noite')));
create table if not exists parts(id bigint generated always as identity primary key,part_code char(8) unique not null check(part_code ~ '^[0-9]{8}$'),description text not null,client_id bigint references clients(id));
create table if not exists operations(id bigint generated always as identity primary key,part_id bigint not null references parts(id) on delete cascade,operation_code text not null,minutes_per_piece numeric not null check(minutes_per_piece>0),setup_hours numeric not null default 0,unique(part_id,operation_code));
create table if not exists operation_machine_groups(id bigint generated always as identity primary key,operation_id bigint not null references operations(id) on delete cascade,machine_group text not null,unique(operation_id,machine_group));
create table if not exists planning(id bigint generated always as identity primary key,machine_id bigint not null references machines(id),operation_id bigint not null references operations(id),quantity integer not null check(quantity>0),start_date date not null,morning_employee_id bigint references employees(id),afternoon_employee_id bigint references employees(id),night_employee_id bigint references employees(id),status text not null default 'Programada' check(status in ('Programada','Concluída')),created_at timestamptz default now());
